import { ref, watch, onMounted } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
export default {
  __name: 'DeleteNetworkDialog',
  props: {
    modelValue: Boolean
  },
  emits: ['update:modelValue', 'refresh'],
  setup(__props, {
    expose: __expose,
    emit: __emit
  }) {
    const props = __props;
    const emit = __emit;
    const visible = ref(false);
    const form = ref({
      networkName: ''
    });
    const networkNames = ref([]);
    const fetchNetworkNames = async () => {
      try {
        const res = await axios.get('/network/list');
        networkNames.value = Object.keys(res.data);
      } catch (err) {
        ElMessage.error('获取网络列表失败');
      }
    };
    const openDialog = () => {
      fetchNetworkNames();
      visible.value = true;
    };
    const closeDialog = () => {
      visible.value = false;
      form.value.networkName = '';
    };
    const submitDelete = async () => {
      if (!form.value.networkName) {
        ElMessage.warning('请选择网络名称');
        return;
      }
      try {
        await axios.delete(`/network/delete/${form.value.networkName}`);
        ElMessage.success('删除成功');
        emit('refresh');
        closeDialog();
      } catch (err) {
        ElMessage.error('删除失败');
      }
    };

    // 暴露方法给父组件使用
    __expose({
      openDialog
    });
    const __returned__ = {
      props,
      emit,
      visible,
      form,
      networkNames,
      fetchNetworkNames,
      openDialog,
      closeDialog,
      submitDelete,
      ref,
      watch,
      onMounted,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
